    "text": "While I was thus mutely pondering within myself, and recording my sorrowful complainings with my pen, it seemed to me that there appeared above my head a woman of a countenance exceeding venerable. Her eyes were bright as fire, and of a more than human keenness; her complexion was lively, her vigour showed no trace of enfeeblement; and yet her years were right full, and she plainly seemed not of our age and time. Her stature was difficult to judge. At one moment it exceeded not the common height, at another her forehead seemed to strike the sky; and whenever she raised her head higher, she began to pierce within the very heavens, and to baffle the eyes of them that looked upon her. Her garments were of an imperishable fabric, wrought with the finest threads and of the most delicate workmanship; and these, as her own lips afterwards assured me, she had herself woven with her own hands.",
