    "text": "You have a consul who has been preserved from very many perils and secret treacheries, yes, from the very jaws of death, not for the prolongation of his own life but for the promotion of your welfare. All the privileged orders are united in heart and mind and voice for the preservation of the commonwealth. The native land of all of us, beset by the firebrands and swords of an infamous conspiracy, extends to you her suppliant hands; to you she commits herself, to you the lives of all her citizens, to you the citadel and the Capitol, to you the altars of the Penates, to you the eternal fire of Vesta burning yonder, to you the temples and shrines of all the gods, to you the walls and buildings of the city. On the fate moreover of your own lives, of the souls of your wives and children, of the properties of all, of your homes and your hearths, you have yourselves to decide this very day.",
