    "text": "Cocles, (that defence the fortune of Rome had on that day,) who, happening to be posted on guard at the bridge, when he saw the Janiculum taken by a sudden assault, and that the enemy were pouring down from thence in full speed, and that his own party, in terror and confusion, were abandoning their arms and ranks, laying hold of them one by one, standing in their way, and appealing to the faith of gods and men, he declared, \"That their flight would avail them nothing if they deserted their post; if they passed the bridge and left it behind them, there would soon be more of the enemy in the Palatium and Capitol than in the Janiculum; for that reason he advised and charged them to demolish the bridge, by their sword, by fire, or by any means whatever; that he would stand the shock of the enemy as far as could be done by one man.\" He then advances to the first entrance of the bridge, and being easily distinguished among those who showed their backs in retreating from the fight, facing about to engage the foe hand to hand, by his surprising bravery he terrified the enemy.",
