    "text": "Too late loved I Thee, O Thou Beauty of ancient days, yet ever new! too late I loved Thee! And behold, Thou wert within, and I abroad, and there I searched for Thee; deformed I, plunging amid those fair forms which Thou hadst made. Thou wert with me, but I was not with Thee. Things held me far from Thee, which, unless they were in Thee, were not at all. Thou calledst, and shoutedst, and burstest my deafness. Thou flashedst, shonest, and scatteredst my blindness. Thou breathedst odours, and I drew in breath and panted for Thee. I tasted, and hunger and thirst. Thou touchedst me, and I burned for Thy peace. When I shall with my whole self cleave to Thee, I shall no where have sorrow or labour; and my life shall wholly live, as wholly full of Thee. But now since whom Thou fillest, Thou liftest up, because I am not full of Thee I am a burden to myself.",
