    "cue": "Truth must not stand unarmed against falsehood: the Christian may use rhetoric.",
    "text": "Now, the art of rhetoric being available for the enforcing either of truth or falsehood, who will dare to say that truth in the person of its defenders is to take its stand unarmed against falsehood? For example, that those who are trying to persuade men of what is false are to know how to introduce their subject, so as to put the hearer into a friendly, or attentive, or teachable frame of mind, while the defenders of the truth shall be ignorant of that art? That the former are to tell their falsehoods briefly, clearly, and plausibly, while the latter shall tell the truth in such a way that it is tedious to listen to, hard to understand, and, in fine, not easy to believe it?",
