    "text": "Accordingly a great orator has truly said that an eloquent man must speak so as to teach, to delight, and to persuade. Then he adds: To teach is a necessity, to delight is a beauty, to persuade is a triumph. Now of these three, the one first mentioned, the teaching, which is a matter of necessity, depends on what we say; the other two on the way we say it. He, then, who speaks with the purpose of teaching should not suppose that he has said what he has to say as long as he is not understood.",
